package co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.interactor.impl;
import co.edu.uco.seguridad.pdp.applications.application.rule.validator.ApplicationOwnerLookupValidator; import co.edu.uco.seguridad.pdp.authorization.application.primaryport.request.*; import co.edu.uco.seguridad.pdp.authorization.application.usecase.ListApplicationSecurityRolesUseCase; import co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.dto.request.raw.*; import co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.dto.response.ApplicationSecurityRoleWebResponse; import co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.interactor.ListApplicationSecurityRolesInteractor; import co.edu.uco.seguridad.pdp.authorization.infrastructure.adapter.primary.web.mapper.ApplicationSecurityPageRequestMapper; import co.edu.uco.seguridad.pdp.commons.model.*; import co.edu.uco.seguridad.pdp.identity.application.rule.validator.SubjectUserIdLookupValidator; import co.edu.uco.seguridad.shared.security.*; import co.edu.uco.seguridad.shared.web.*; import reactor.core.publisher.Mono; import java.util.Set;
public final class ListApplicationSecurityRolesInteractorImpl implements ListApplicationSecurityRolesInteractor {private final ApplicationOwnerLookupValidator owner;private final SubjectUserIdLookupValidator ids;private final ListApplicationSecurityRolesUseCase useCase;public ListApplicationSecurityRolesInteractorImpl(ApplicationOwnerLookupValidator owner,SubjectUserIdLookupValidator ids,ListApplicationSecurityRolesUseCase useCase){this.owner=owner;this.ids=ids;this.useCase=useCase;}public Mono<PageResponse<ApplicationSecurityRoleWebResponse>> execute(ListApplicationSecurityRawRequest r){ApplicationId app=RequestFieldParser.parse("applicationId",r.applicationId(),ApplicationId::of);PageWindow w=ApplicationSecurityPageRequestMapper.toWindow(new ApplicationSecurityPageRawRequest(r.page(),r.size(),r.offset(),r.limit()));return SecurityContext.currentPrincipal().flatMap(p->user(p).flatMap(u->owner.execute(app).map(t->new AdministrationRequest(t,app,u,p.subject(),Set.of(),p.authenticationContext())))).flatMap(a->useCase.execute(new ListApplicationSecurityRolesRequest(a,w))).map(p->new PageResponse<>(p.content().stream().map(x->new ApplicationSecurityRoleWebResponse(x.id().value().toString(),x.name().value(),x.resources().size(),x.registeredAt().toString())).toList(),p.total(),p.window().page(),p.window().offset(),p.window().limit()));}private Mono<UserId> user(PdpPrincipal p){return p.userId().map(Mono::just).orElseGet(()->ids.execute(p.subject()));}}
